"""Writes vars.cpp: variants of the Neon 16x8 Hadamard kernel for timing on the Arm CI runner.
usage: make_vars.py <master RdCost_neon.cpp> <fixed RdCost_neon.cpp> <output vars.cpp>

Each variant is the full xCalcHAD16x8_neon function under another name, so the compiler treats it like the real one:
  V0 master   (overflows for 12-bit residuals: speed reference only)
  V1 fix      (PR #731 as it is: helper on &m1[k])
  V2 fix with explicit vaddl_high_s16 / vsubl_high_s16 in the helper
  V3 fix with the four rows passed by value instead of through a pointer
  V4 fix with the helper's maxima kept in four separate accumulators
"""
import re
import sys

master_src = open(sys.argv[1], encoding="utf-8").read().replace("\r\n", "\n")
fix_src = open(sys.argv[2], encoding="utf-8").read().replace("\r\n", "\n")


def function(src, name):
    start = src.index("Distortion " + name + "(")
    end = src.index("\n}\n", start) + 3
    return src[start:end]


def helper(src):
    start = src.index("// Applies the 8-point Hadamard butterflies within each of the four vectors")
    end = src.index("\n}\n", start) + 3
    return src[start:end]


master_fn = function(master_src, "xCalcHAD16x8_neon")
fix_fn = function(fix_src, "xCalcHAD16x8_neon")
fix_helper = helper(fix_src)

out = []
out.append('''// Generated by make_vars.py: variants of the Neon 16x8 Hadamard kernel (see there).
#include <arm_neon.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>

#include "CommonLib/RdCost.h"
#include "CommonLib/arm/neon/sum_neon.h"
#include "CommonLib/arm/neon/transpose_neon.h"

namespace vvenc
{
''')

# V0 master
out.append(master_fn.replace("xCalcHAD16x8_neon(", "had16x8_V0(", 1))

# V1 fix as is
out.append(fix_helper)
out.append(fix_fn.replace("xCalcHAD16x8_neon(", "had16x8_V1(", 1))

# V2 explicit high-half widening
h2 = fix_helper.replace("hadamard8x4RowsHalfAbs(", "hadamard8x4RowsHalfAbs_V2(", 1)
h2 = re.sub(r"vaddl_s16\( vget_high_s16\( (\w+) \), vget_high_s16\( (\w+) \) \)", r"vaddl_high_s16( \1, \2 )", h2)
h2 = re.sub(r"vsubl_s16\( vget_high_s16\( (\w+) \), vget_high_s16\( (\w+) \) \)", r"vsubl_high_s16( \1, \2 )", h2)
assert h2.count("vaddl_high_s16") == 2 and h2.count("vsubl_high_s16") == 2
out.append(h2)
out.append(fix_fn.replace("xCalcHAD16x8_neon(", "had16x8_V2(", 1).replace("hadamard8x4RowsHalfAbs(", "hadamard8x4RowsHalfAbs_V2("))

# V3 rows by value
h3 = h2.replace("hadamard8x4RowsHalfAbs_V2( const int16x8_t row[4] )",
                "hadamard8x4RowsHalfAbs_V3( const int16x8_t row0, const int16x8_t row1, const int16x8_t row2, const int16x8_t row3 )")
for i in range(4):
    h3 = h3.replace("row[%d]" % i, "row%d" % i)
out.append(h3)
v3 = fix_fn.replace("xCalcHAD16x8_neon(", "had16x8_V3(", 1)
call = "hadamard8x4RowsHalfAbs( &m1[k] )"
assert call in v3
v3 = v3.replace(call, "hadamard8x4RowsHalfAbs_V3( m1[k], m1[k + 1], m1[k + 2], m1[k + 3] )")
out.append(v3)

# V4 separate accumulators for the four maxima
h4 = h2.replace("static inline int32x4_t hadamard8x4RowsHalfAbs_V2( const int16x8_t row[4] )",
                "static inline void hadamard8x4RowsHalfAbs_V4( const int16x8_t row[4], int32x4_t acc[4] )")
tail_old = h4[h4.index("  const int32x4_t max01"):h4.rindex("}")]
h4 = h4.replace(tail_old, "  acc[0] = vaddq_s32( acc[0], vmaxq_s32( absLo0, absHi0 ) );\n"
                          "  acc[1] = vaddq_s32( acc[1], vmaxq_s32( absLo1, absHi1 ) );\n"
                          "  acc[2] = vaddq_s32( acc[2], vmaxq_s32( absLo2, absHi2 ) );\n"
                          "  acc[3] = vaddq_s32( acc[3], vmaxq_s32( absLo3, absHi3 ) );\n")
out.append(h4)
v4 = fix_fn.replace("xCalcHAD16x8_neon(", "had16x8_V4(", 1)
loop_old = v4[v4.index("  int32x4_t sum = vdupq_n_s32( 0 );"):v4.index("  uint32_t sad = ")]
v4 = v4.replace(loop_old, "  int32x4_t acc[4] = { vdupq_n_s32( 0 ), vdupq_n_s32( 0 ), vdupq_n_s32( 0 ), vdupq_n_s32( 0 ) };\n"
                          "  for( int k = 0; k < 16; k += 4 )\n  {\n    hadamard8x4RowsHalfAbs_V4( &m1[k], acc );\n  }\n"
                          "  const int32x4_t sum = vaddq_s32( vaddq_s32( acc[0], acc[1] ), vaddq_s32( acc[2], acc[3] ) );\n\n")
out.append(v4)

out.append('''
}   // namespace vvenc

using namespace vvenc;
typedef Distortion ( *Kernel )( const Pel*, const Pel*, const ptrdiff_t, const ptrdiff_t );

int main( int argc, char** argv )
{
  const long calls = argc > 1 ? atol( argv[1] ) : 2000000;
  const Kernel kernels[] = { had16x8_V0, had16x8_V1, had16x8_V2, had16x8_V3, had16x8_V4 };
  const int numKernels = 5;

  RdCost scalar;
  scalar.create( /*enableOpt=*/false );

  const int stride = 256 + 64;
  std::vector<Pel> org( stride * 256 ), cur( stride * 256 );

  // exactness against the C code: random 10-bit, and residuals of +-2046 (V0, master, fails those)
  srand( 3 );
  int bad[numKernels] = {};
  for( int trial = 0; trial < 4000; trial++ )
  {
    const int pattern = trial % 4;   // 0: random 10-bit, 1: +2046, 2: -2046, 3: random signs of 2046
    for( size_t i = 0; i < org.size(); i++ )
    {
      if( pattern == 0 ) { org[i] = Pel( rand() & 1023 ); cur[i] = Pel( rand() & 1023 ); continue; }
      const bool positive = pattern == 1 || ( pattern == 3 && ( rand() & 1 ) );
      org[i] = Pel( positive ? 2046 : -1023 );
      cur[i] = Pel( positive ? 0 : 1023 );
    }
    DistParam dp;
    dp.org.buf = org.data(); dp.org.stride = stride; dp.org.width = 16; dp.org.height = 8;
    dp.cur.buf = cur.data(); dp.cur.stride = stride;
    dp.bitDepth = 10; dp.applyWeight = 0;
    const Distortion ref = scalar.m_afpDistortFunc[0][DF_HAD16]( dp );
    for( int v = 0; v < numKernels; v++ )
    {
      bad[v] += kernels[v]( org.data(), cur.data(), stride, stride ) != ref;
    }
  }
  for( int v = 0; v < numKernels; v++ )
  {
    printf( "V%d mismatches against the C code: %d of 4000\\n", v, bad[v] );
  }

  srand( 1 );
  for( auto& v : org ) v = Pel( rand() & 1023 );
  for( size_t i = 0; i < cur.size(); i++ ) cur[i] = Pel( std::min( 1023, std::max( 0, org[i] + ( rand() % 64 ) - 32 ) ) );

  double best[numKernels];
  std::fill( best, best + numKernels, 1e9 );
  for( int round = 0; round < 5; round++ )
  {
    for( int v = 0; v < numKernels; v++ )
    {
      uint64_t checksum = 0;
      const auto start = std::chrono::steady_clock::now();
      for( long i = 0; i < calls; i++ )
      {
        const int x = ( i * 37 ) % ( 256 - 16 ), y = ( i * 11 ) % ( 256 - 8 );
        checksum += kernels[v]( &org[y * stride + x], &cur[( ( y + 3 ) % ( 256 - 8 ) ) * stride + x], stride, stride );
      }
      const double ns = std::chrono::duration<double, std::nano>( std::chrono::steady_clock::now() - start ).count() / calls;
      best[v] = std::min( best[v], ns );
      printf( "round %d V%d %7.2f ns/call checksum %llu\\n", round, v, ns, (unsigned long long) checksum );
    }
  }
  for( int v = 0; v < numKernels; v++ )
  {
    printf( "V%d best %7.2f ns/call (%+.1f %% against V0)\\n", v, best[v], ( best[v] / best[0] - 1 ) * 100 );
  }
  return 0;
}
''')
open(sys.argv[3], "w", encoding="utf-8").write("\n".join(out))
print("ok")
